import{_ as o,H as a,f as i,i as t}from"./chunks/framework.BauLNg70.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"es/index.md","filePath":"es/index.md"}'),n={name:"es/index.md"};function s(l,e,r,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<hr><p>layout: home</p><p>hero: name: Mods para Snake Classic text: Doc oficial para autores de mods. tagline: | Personaliza power-ups, velocidad, progresión y UI sin compilar el juego. Sandbox por diseño, compatible con cualquier bundle del estudio (standalone + Classics Reloaded). actions: - theme: brand text: Empezar link: /es/tutorial/01-hello-mod - theme: alt text: Mira el template link: <a href="https://github.com/leteoworks/mod-template-snake-classic" target="_blank" rel="noreferrer">https://github.com/leteoworks/mod-template-snake-classic</a> - theme: alt text: Steam Workshop link: <a href="https://steamcommunity.com/app/TBD/workshop/" target="_blank" rel="noreferrer">https://steamcommunity.com/app/TBD/workshop/</a></p><p>features:</p><ul><li>icon: 📦 title: Manifest declarativo details: | Un solo <code>mod.json</code> describe permisos, engine, eventos, settings UI, assets, i18n. El framework valida con Zod antes de cargar. link: /es/manifest-format</li><li>icon: 🎛️ title: UI con componentes oficiales details: | No tienes que pelear con CSS. Declara tabs/sliders/toggles con tokens semánticos y el juego renderiza con su look coherente. link: /storybook/index.html</li><li>icon: 🔐 title: Sandbox por diseño details: | Sin <code>fetch</code>, sin <code>window</code>, sin <code>require</code>. El host expone una API controlada y el juego garantiza que un mod no puede tirarlo. link: /es/api-reference</li><li>icon: 🚀 title: Workshop nativo details: | Publica desde Steam → un <code>.zip</code> con tu manifest + dist y listo. Auto-update, auto-discovery, kill-switch reactivo del estudio. link: /es/publishing</li><li>icon: 🧩 title: Multi-engine details: | Elige el motor según tus necesidades. QuickJS por defecto; isolated-vm, iframe-sandbox, web-worker-offscreen-canvas u otros según features. link: /es/multi-engine</li><li>icon: 🎯 title: Targeting al <code>gameId</code> details: | Tu mod apunta a <code>snake-classic</code> y funciona en cualquier bundle que monte el juego (standalone, Classics Reloaded…). Sin duplicar publicaciones. link: /es/targeting-games</li></ul><hr><h2 id="¿que-encontraras-aqui" tabindex="-1">¿Qué encontrarás aquí? <a class="header-anchor" href="#¿que-encontraras-aqui" aria-label="Permalink to &quot;¿Qué encontrarás aquí?&quot;">​</a></h2><ul><li><strong>Tutoriales</strong> paso a paso para tu primer mod.</li><li><strong>Referencia completa</strong> del <code>mod.json</code> y del <code>HostBridge</code>.</li><li><strong>Catálogo visual</strong> de componentes UI declarativos disponibles.</li><li><strong>Guía de publicación</strong> a Steam Workshop (incluyendo flow de verificación opcional cuando se active).</li><li><strong>Ejemplos reales</strong> clonables — empezando por el mod oficial &quot;Fun Config&quot; que sirve de referencia viva.</li></ul><h2 id="¿quien-mantiene-esto" tabindex="-1">¿Quién mantiene esto? <a class="header-anchor" href="#¿quien-mantiene-esto" aria-label="Permalink to &quot;¿Quién mantiene esto?&quot;">​</a></h2><p>El portal lo mantiene el equipo de Leteo Works. Issues, sugerencias y PRs vienen por GitHub. Bugs del juego o del runtime van por el repo principal; bugs de docs vienen aquí.</p><h2 id="conducta-esperada-de-la-comunidad" tabindex="-1">Conducta esperada de la comunidad <a class="header-anchor" href="#conducta-esperada-de-la-comunidad" aria-label="Permalink to &quot;Conducta esperada de la comunidad&quot;">​</a></h2><p>Mods que ejecuten malware, doxxen jugadores, o filtren datos serán <strong>reportados a Steam y kill-switch-eados</strong> desde nuestro panel de operación. El sandbox del runtime ya impide la mayoría de vectores, pero la responsabilidad final es del modder.</p><p>Para todo lo demás: enjoy + experimenta sin miedo. Hacer mods debe ser divertido.</p>',13)])])}const g=o(n,[["render",s]]);export{m as __pageData,g as default};
